<?php
declare(strict_types=1);require_once __DIR__.'/billing_common.php';$user=billing_require_admin();production_require_method('GET');accounts_endpoint(function():array{$db=production_db();$asOf=accounts_date($_GET['as_of']??gmdate('Y-m-d'));$s=$db->prepare("SELECT i.id,i.reference_no,i.client_id,i.client_name_snapshot,i.invoice_date,i.due_date,i.total_amount,COALESCE((SELECT SUM(a.cash_amount+a.wht_amount) FROM qbook_customer_receipt_allocations a JOIN qbook_customer_receipts r ON r.id=a.receipt_id AND r.status='POSTED' WHERE a.invoice_id=i.id),0)+COALESCE((SELECT SUM(a.amount) FROM qbook_advance_applications a WHERE a.invoice_id=i.id),0)+COALESCE((SELECT SUM(ca.amount) FROM qbook_credit_note_allocations ca JOIN qbook_credit_notes c ON c.id=ca.credit_note_id AND c.status='ISSUED' WHERE ca.invoice_id=i.id),0) settled FROM qbook_invoices i WHERE i.status='ISSUED' AND i.invoice_date<=? ORDER BY i.client_name_snapshot,i.invoice_date");$s->execute([$asOf]);$b=['CURRENT'=>0,'1_30'=>0,'31_60'=>0,'61_90'=>0,'OVER_90'=>0];$rows=[];foreach($s->fetchAll()as$r){$out=accounts_money_minor($r['total_amount'],false)-accounts_money_minor((string)$r['settled'],false);if($out<=0)continue;$days=$r['due_date']===null?0:(int)(new DateTimeImmutable($r['due_date']))->diff(new DateTimeImmutable($asOf))->format('%r%a');$key=$r['due_date']===null||$days<=0?'CURRENT':($days<=30?'1_30':($days<=60?'31_60':($days<=90?'61_90':'OVER_90')));$b[$key]+=$out;$r['reference']=billing_ref('INVOICE',$r['reference_no']);$r['outstanding']=accounts_minor_decimal($out);$r['bucket']=$key;$rows[]=$r;}return['as_of'=>$asOf,'buckets'=>array_map('accounts_minor_decimal',$b),'invoices'=>$rows];});
